package net.officefloor.hq.app.crew;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored crews and their members, kept per sheet. */
@Repository
public class CrewRepository {

    private final JdbcTemplate jdbc;

    public CrewRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's crews in the order added, each with its lead and its members in the order added. */
    public List<Crew> list(String sheetId) {
        Map<Long, Crew> crews = new LinkedHashMap<>();
        jdbc.query("SELECT c.id, c.name, c.lead_id, p.name AS lead FROM crew c JOIN person p ON p.id = c.lead_id"
                + " WHERE c.sheet_id = ? ORDER BY c.id",
                rs -> {
                    crews.put(rs.getLong("id"), new Crew(rs.getString("name"), rs.getLong("lead_id"),
                            rs.getString("lead"), new ArrayList<>()));
                }, sheetId);
        jdbc.query("SELECT m.crew_id, m.person_id, p.name FROM crew_member m JOIN crew c ON c.id = m.crew_id"
                + " JOIN person p ON p.id = m.person_id WHERE c.sheet_id = ? ORDER BY m.id",
                rs -> {
                    Crew crew = crews.get(rs.getLong("crew_id"));
                    if (crew != null) {
                        crew.members().add(new CrewMember(rs.getLong("person_id"), rs.getString("name")));
                    }
                }, sheetId);
        return new ArrayList<>(crews.values());
    }

    /** Adds the crew; false when the name is already taken on the sheet (the unique key refuses a second). */
    public boolean add(String sheetId, String name, long leadId) {
        try {
            jdbc.update("INSERT INTO crew (sheet_id, name, lead_id) VALUES (?, ?, ?)", sheetId, name, leadId);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** The id of the sheet's crew by that name, or null when there is none. */
    public Long idOf(String sheetId, String name) {
        List<Long> ids = jdbc.queryForList("SELECT id FROM crew WHERE sheet_id = ? AND name = ?", Long.class, sheetId,
                name);
        return ids.isEmpty() ? null : ids.get(0);
    }

    /** The id of the crew's lead. */
    public long leadOf(long crewId) {
        return jdbc.queryForObject("SELECT lead_id FROM crew WHERE id = ?", Long.class, crewId);
    }

    /** The name of the person on the sheet, or null when there is no such person there. */
    public String personName(String sheetId, long personId) {
        List<String> names = jdbc.queryForList("SELECT name FROM person WHERE sheet_id = ? AND id = ?", String.class,
                sheetId, personId);
        return names.isEmpty() ? null : names.get(0);
    }

    /** Adds the person to the crew; false when they are already in it. */
    public boolean addMember(long crewId, long personId) {
        try {
            jdbc.update("INSERT INTO crew_member (crew_id, person_id) VALUES (?, ?)", crewId, personId);
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }
}
package net.officefloor.hq.app.crew;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the crew's name, trimmed, is not blank, and a lead is chosen. */
public class ValidateCrew {
    public void validate(@RequestBody CrewRequest request, Out<CrewRequest> body) throws InvalidCrewException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidCrewException("A crew's name must not be blank");
        }
        if (request.leadId() == null) {
            throw new InvalidCrewException("A crew needs a lead");
        }
        body.set(request);
    }
}
package net.officefloor.hq.app.crew;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores the crew on the sheet; an unknown lead, or a name already taken there, is refused. */
public class AddCrew {
    public void add(@PathVariable("sheetId") String sheetId, @Val CrewRequest request, CrewRepository crews,
            Out<CrewValues> values) throws InvalidCrewException {
        String sheet = sheetId.trim();
        String name = request.name().trim();
        String lead = crews.personName(sheet, request.leadId());
        if (lead == null) {
            throw new InvalidCrewException("No such person on the sheet");
        }
        if (!crews.add(sheet, name, request.leadId())) {
            throw new InvalidCrewException(name + " is already a crew");
        }
        values.set(new CrewValues(name, request.leadId(), lead, request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.pool;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: the pool's name, trimmed, is not blank. */
public class ValidatePool {
    public void validate(@RequestBody PoolRequest request, Out<PoolValues> values) throws InvalidPoolException {
        String name = request == null || request.name() == null ? "" : request.name().trim();
        if (name.isEmpty()) {
            throw new InvalidPoolException("A pool's name must not be blank");
        }
        values.set(new PoolValues(name, request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.pool;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Stores the pool on the sheet; a name already taken there is refused. */
public class AddPool {
    public void add(@PathVariable("sheetId") String sheetId, @Val PoolValues values, PoolRepository pools)
            throws InvalidPoolException {
        if (!pools.add(sheetId.trim(), values.name())) {
            throw new InvalidPoolException(values.name() + " is already a pool");
        }
    }
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.util.List;

/** A pool of the sheet: its members, the total of their shares (a retired member's counting as given), and whether that
 *  total is exactly 100.00. */
public record Pool(String name, List<PoolMember> members, BigDecimal totalShare, boolean balanced) {
}
package net.officefloor.hq.app.pool;

import java.math.BigDecimal;

/** A member of a pool: a person (personId and name) or another pool (pool, its name; personId null), the share percent,
 *  whether the person is retired (then their share still counts toward the total but they get no cut; a pool never
 *  is), and the cut of the pool's pot (two
 *  decimals; null when the pool is not balanced or has no pot). A membership may carry a from-date and a to-date
 *  (yyyy-MM-dd, null for none); active is whether they include the sheet's today: an inactive member is left out
 *  entirely (not in the total, no cut). */
public record PoolMember(Long personId, String name, String pool, BigDecimal share, boolean retired, String cut,
        String from, String to, boolean active) {

    /** The member with their cut of the pot (an inactive member never has one). */
    public PoolMember withCut(BigDecimal cut) {
        return new PoolMember(personId, name, pool, share, retired,
                cut == null || !active ? null : cut.toPlainString(), from, to, active);
    }
}
package net.officefloor.hq.app.pool;

import java.util.List;
import net.officefloor.hq.app.sheet.AsOf;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** The sheet's pools in the order added, each with its members, total share and whether it is balanced. Read as of a
 *  date (see AsOf), the date stands in for the sheet's today. */
public class RespondWithPools {
    public void respond(@PathVariable("sheetId") String sheetId,
            @RequestParam(value = "asOf", required = false) String asOf, PoolRepository pools,
            ObjectResponse<List<Pool>> response) {
        response.send(pools.list(sheetId.trim(), AsOf.parse(asOf)));
    }
}
package net.officefloor.hq.app.patron;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

/** The stored patrons, kept per sheet. */
@Repository
public class PatronRepository {

    private final JdbcTemplate jdbc;
    private final SheetRepository sheets;

    public PatronRepository(JdbcTemplate jdbc, SheetRepository sheets) {
        this.jdbc = jdbc;
        this.sheets = sheets;
    }

    public List<Patron> list(String sheetId) {
        return jdbc.query("SELECT person_id, patron_id FROM patron WHERE sheet_id = ? ORDER BY person_id, named_seq",
                (rs, n) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id")), sheetId);
    }

    /** Names the patron for the person; false when they already had them (the primary key refuses a second). */
    public boolean add(String sheetId, long personId, long patronId) {
        try {
            jdbc.update("INSERT INTO patron (sheet_id, person_id, patron_id, added_on) VALUES (?, ?, ?, ?)", sheetId, personId, patronId,
                    java.sql.Date.valueOf(sheets.today(sheetId)));
            return true;
        } catch (DuplicateKeyException e) {
            return false;
        }
    }

    /** As they stood at the end of the date: only those started while the sheet's today was on or before it. */
    public List<Patron> listAsOf(String sheetId, java.time.LocalDate date) {
        return jdbc.query("SELECT person_id, patron_id FROM patron WHERE sheet_id = ? AND (added_on IS NULL OR added_on <= ?) ORDER BY person_id, named_seq",
                (rs, n) -> new Patron(rs.getLong("person_id"), rs.getLong("patron_id")), sheetId, java.sql.Date.valueOf(date));
    }
}
